fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn disc(cx: i32, cy: i32, r: i32, rgb: i32) {
    host::display::fill_rect(cx - r, cy - r, 2 * r, 2 * r, rgb);
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, h + 20);
        host::display::state_set(2, h + 220);
        host::display::state_set(3, 1);
        host::display::state_set(4, 2);
        host::display::state_set(5, 0);
        host::display::state_set(6, 0);
        host::display::state_set(7, 0);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(8) == 0;
    host::display::state_set(8, down);
    if host::display::state_get(7) == 1 {
        host::display::clear(0x081018);
        host::display::draw_string(110, 180, "THEY GOT AWAY", 0xff4040, 3);
        host::display::draw_string(140, 250, "POPPED", 0x808080, 2);
        host::display::draw_number(280, 244, host::display::state_get(5), 0xffffff, 3);
        host::display::draw_string(140, 320, "TAP TO RESTART", 0x808080, 2);
        if tap { host::display::state_set(0, 0); }
    } else {
        host::display::clear(0x081018);
        let px: i32 = host::display::pointer_x();
        let py: i32 = host::display::pointer_y();
        let mut i: i32 = 0;
        while i < 2 {
            let rnd: i32 = host::display::state_get(3 + i);
            let bx: i32 = 30 + hash(rnd * 11 + i) % (w - 60);
            let spd: i32 = 2 + hash(rnd * 5 + i) % 3;
            let mut by: i32 = host::display::state_get(1 + i);
            by = by - spd;
            let mut popped: i32 = 0;
            if tap {
                let dx: i32 = px - bx;
                let dy: i32 = py - by;
                if dx * dx + dy * dy <= 576 {
                    popped = 1;
                    host::audio::tone(660, 60, 0);
                    host::display::state_set(5, host::display::state_get(5) + 1);
                }
            }
            if by < -20 && popped == 0 {
                let esc: i32 = host::display::state_get(6) + 1;
                host::display::state_set(6, esc);
                if esc >= 3 { host::display::state_set(7, 1); }
                popped = 1;
            }
            if popped == 1 {
                host::display::state_set(3 + i, rnd + 1);
                by = h + 20 + hash(rnd * 17 + i) % 100;
            }
            host::display::state_set(1 + i, by);
            disc(bx, by, 18, 0x2255aa);
            disc(bx, by, 14, 0x4488ff);
            disc(bx - 6, by - 6, 4, 0xbbddff);
            i = i + 1;
        }
        host::display::draw_string(8, 8, "POPPED", 0x808080, 2);
        host::display::draw_number(140, 8, host::display::state_get(5), 0x00ff88, 2);
        host::display::draw_string(w - 200, 8, "ESCAPED", 0x808080, 2);
        host::display::draw_number(w - 50, 8, host::display::state_get(6), 0xff4040, 2);
    }
    host::display::present();
}
